import urllib.request
import urllib.error
import time
from typing import Optional


class RateLimitError(Exception):
    """Raised when the server returns a 429 Too Many Requests error."""
    pass


class ServerError(Exception):
    """Raised when the server returns a 5xx error after retry attempts."""
    pass


class ClientError(Exception):
    """Raised when the client encounters a 4xx error (excluding 429)."""
    pass


class ConnectionError(Exception):
    """Raised when a network error occurs after retry attempts."""
    pass


class APIClient:
    def __init__(self, base_url: str, timeout: int = 10):
        self.base_url = base_url
        self.timeout = timeout

    def _make_request(self, path: str) -> str:
        url = f"{self.base_url}{path}"
        req = urllib.request.Request(url)

        # Define retry logic
        max_retries = 3
        backoff_times = [0.5, 1.0, 2.0]

        for attempt in range(max_retries):
            try:
                with urllib.request.urlopen(req, timeout=self.timeout) as response:
                    return response.read().decode('utf-8')
            except urllib.error.HTTPError as e:
                status_code = e.code

                if status_code == 429:
                    if attempt < len(backoff_times):
                        time.sleep(backoff_times[attempt])
                        continue
                    raise RateLimitError(f"Rate limit exceeded after {attempt + 1} attempts")

                elif 500 <= status_code < 600:
                    if attempt == 0:
                        time.sleep(1.0)
                        continue
                    raise ServerError(f"Server error {status_code} after retry")

                elif 400 <= status_code < 500:
                    raise ClientError(f"Client error {status_code}: {e.reason}")

                else:
                    # Unknown HTTP error, treat as client error for safety
                    raise ClientError(f"Unknown HTTP error {status_code}: {e.reason}")

            except urllib.error.URLError as e:
                if attempt == 0:
                    time.sleep(1.0)
                    continue
                raise ConnectionError(f"Connection failed: {e.reason}")

            except Exception as e:
                # Catch any other unexpected errors during request
                raise ConnectionError(f"Unexpected error: {str(e)}")

        # This part should theoretically not be reached due to the loop logic above
        if status_code == 429:
            raise RateLimitError("Rate limit exceeded after all retries")
        elif 500 <= status_code < 600:
            raise ServerError("Server error after all retries")
        elif 400 <= status_code < 500:
            raise ClientError("Client error after all retries")
        else:
            raise ConnectionError("Connection failed after all retries")

    def get(self, path: str) -> str:
        """Makes a GET request and returns the response body as a string."""
        return self._make_request(path)
